import {drawNotebook,drawCastleScenery} from './defense-polish.js';
import {drawWorkshopBackdrop} from './workshop-ui.js';
import {drawWarUnit,drawWarProjectile} from './wars-art.js';
import {drawCastleObject} from './castle-object-art.js';
import {healthBarAlpha} from './castle-upgrades.js';
import {drawRoyalPerson,drawCastleMissile} from './castle-art.js';
import {prepareCanvas} from './touch-render.js';
import {drawBackdrop,drawCharacter,drawFood,drawMaterial,drawTool,drawRagdollPart} from './premium-art.js';
import {CASTLE_PARTS} from './castle-core.js';
import {BUDDY_GADGETS} from './buddy-core.js';
import {ROBOT_TYPES} from './robot-core.js';
const TAU=Math.PI*2;
export function label(c,text,x,y,size=16,color='#e5eef6'){c.font=`600 ${size}px Outfit,Arial`;c.textAlign='center';c.textBaseline='middle';c.fillStyle=color;c.fillText(text,x,y);}
function rect(c,x,y,w,h,fill,stroke='#acbbcc66',r=5){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke();}}
function bar(c,x,y,w,value,color='#8ce3bb'){rect(c,x,y,w,6,'#162b3a',null,3);rect(c,x,y,w*Math.max(0,Math.min(1,value)),6,color,null,3);}
function ring(c,x,y,r,color,width=2){c.beginPath();c.arc(x,y,r,0,TAU);c.strokeStyle=color;c.lineWidth=width;c.stroke();}
export function renderPremium(canvas,m,camera={zoom:1,x:0,y:0}){const {c}=prepareCanvas(canvas);c.save();c.translate(500+camera.x,320+camera.y);c.scale(camera.zoom,camera.zoom);c.translate(-500,-320);if(m.kind==='castle')castle(c,m);if(m.kind==='buddy')buddy(c,m);if(m.kind==='doodle')doodle(c,m);if(m.kind==='robot')robot(c,m);if(m.kind==='wars')wars(c,m);c.restore();}
function castle(c,m){const build=m.phase==='build',supported=build?m.supports():null,sky=c.createLinearGradient(0,0,0,570);sky.addColorStop(0,'#a9cad1');sky.addColorStop(1,'#ecdfb5');c.fillStyle=sky;c.fillRect(0,0,1000,640);c.fillStyle='#fff1b9';c.beginPath();c.arc(760,115,44,0,TAU);c.fill();for(let i=0;i<4;i++){c.fillStyle=['#91b4a4','#80a395','#6a9585','#547e69'][i];c.beginPath();c.moveTo(0,440+i*36);for(let x=0;x<=1000;x+=20)c.lineTo(x,360+i*47+Math.sin(x/170+i*1.8)*45);c.lineTo(1000,640);c.lineTo(0,640);c.fill();}for(let i=0;i<5;i++){const x=(i*240+m.clock*.002)%1200-100;c.fillStyle='#ffffff42';c.beginPath();c.ellipse(x,80+i%3*27,65,15,0,0,TAU);c.fill();}drawCastleScenery(c);c.fillStyle='#9b8d68';c.fillRect(0,570,1000,70);c.fillStyle='#d5ca93';c.fillRect(0,570,1000,6);if(build){c.strokeStyle='#edf3d64d';c.lineWidth=1;for(let x=80;x<960;x+=40){c.beginPath();c.moveTo(x,90);c.lineTo(x,570);c.stroke();}for(let y=90;y<580;y+=40){c.beginPath();c.moveTo(80,y);c.lineTo(940,y);c.stroke();}label(c,'ASSAULT '+(m.wave+1)+' · '+m.plannedCount()+' ENEMY TROOPS INCOMING',500,49,18,'#355c52');label(c,'Build your defenses. Leave a route for your soldiers.',500,76,13,'#526f59');}else if(m.nextWave!==Infinity&&!m.done){label(c,'PREPARE ASSAULT '+(m.wave+1)+' · '+m.plannedCount()+' ENEMIES INCOMING',500,48,17,'#375a50');}
 drawCastleObject(c,m.king,m);const ka=healthBarAlpha(m.king,m.clock);if(ka>0){c.globalAlpha=ka;bar(c,m.king.x-36,480,72,m.coreHP/m.maxCore,'#ce9872');c.globalAlpha=1;}label(c,'PROTECT THE KING',m.king.x,464,11,'#4a6553');
 for(const b of m.items){const r=m.box(b),pos=b.body?.position||b;if(b.type==='flag')continue;if(b.hp<=0&&m.clock-(b.defeatedAt||0)>1200&&b.type==='footman')continue;drawCastleObject(c,b,m);if(build&&!supported.has(b))rect(c,b.x-r.w/2,b.y-r.h/2,r.w,r.h,'#e87b6533','#c66b5d',3);if(m.selected===b)rect(c,pos.x-r.w/2-3,pos.y-r.h/2-3,r.w+6,r.h+6,null,'#fff1b5',5);const alpha=healthBarAlpha(b,m.clock);if(b.hp>0&&alpha>0){b.displayHP=(b.displayHP??b.hp)+(b.hp-(b.displayHP??b.hp))*.2;c.globalAlpha=alpha;bar(c,pos.x-18,pos.y-r.h/2-16,36,b.displayHP/b.maxHP,b.hp/b.maxHP>.5?'#59866b':'#c37c5f');c.globalAlpha=1;}}
 const flag=m.flagAnchor();c.strokeStyle='#655a45';c.lineWidth=3;c.beginPath();c.moveTo(flag.x,flag.y);c.lineTo(flag.x,flag.y-51);c.stroke();c.fillStyle=m.flagColor||'#c98462';c.beginPath();c.moveTo(flag.x+1,flag.y-50);c.quadraticCurveTo(flag.x+16,flag.y-56+Math.sin(m.clock/240)*3,flag.x+31,flag.y-48);c.lineTo(flag.x+25,flag.y-28);c.quadraticCurveTo(flag.x+13,flag.y-34,flag.x+1,flag.y-31);c.closePath();c.fill();label(c,'✦',flag.x+13,flag.y-41,12,'#fff1c8');
 for(const e of m.enemies)if(e.hp>0){if(e.flying)drawCharacter(c,'monster',e.x,e.y,.43,{variant:1,color:'#a76e75',time:m.clock});else drawRoyalPerson(c,{x:e.x,y:570,type:e.id==='knight'||e.id==='boss'?'knight':'footman',side:0,clock:m.clock,scale:e.id==='boss'?.63:.43,walking:e.x<(m.items.find(b=>b.hp>0)?.x||m.king.x)-e.range,hp:e.hp/e.maxHP,attack:Math.max(0,1-(e.cooldown-m.clock)/1400)});bar(c,e.x-18,e.id==='boss'?496:e.flying?e.y-50:516,36,e.hp/e.maxHP,'#b66e6d');}for(const p of m.projectiles)drawCastleMissile(c,p);for(const e of m.effects){c.globalAlpha=e.t/600;ring(c,e.x,e.y,20+(600-e.t)/20,'#f9e3a2',4);}c.globalAlpha=1;}
function articulated(c,doll,kind,options={}){for(const [i,b]of doll.parts.entries()){const s=doll.scale,w=(i===0?33:i===1?42:i<4?15:17)*s,h=(i===0?52:i===1?42:38)*s;drawRagdollPart(c,i===0?'torso':i===1?'head':i<4?'arm':'leg',b.position.x,b.position.y,w,h,b.angle,{kind:kind==='buddy'?'buddy':'unit',...options});}}
function buddy(c,m){drawBackdrop(c,m.room.name,m.clock);for(const target of m.targets){const y=m.mode==='target'?target.y+Math.sin(m.clock/1000+target.x)*35:target.y;ring(c,target.x,y,target.r,target.hit?'#88e0bd':'#efc78a',4);ring(c,target.x,y,target.r*.65,target.hit?'#7ccbad88':'#e6d3a080',2);label(c,target.hit?'✓':'✦',target.x,y,24,target.hit?'#b9f4d7':'#fae2b3');}for(const b of m.physics.M.Composite.allBodies(m.physics.engine.world)){if(m.doll.parts.includes(b)||!b.isStatic||b.position.x<0||b.position.x>1000||b.position.y>630)continue;c.save();c.translate(b.position.x,b.position.y);c.rotate(b.angle);if(b.circleRadius){ring(c,0,0,b.circleRadius,'#9dded1',8);ring(c,0,0,b.circleRadius*.7,'#9b95d2',6);}else rect(c,-90,-11,180,22,'#85cbb8','#b9f3dd',9);c.restore();}for(const g of m.gadgets){const p=g.body?.position||g;if(g.body&&!g.body.isStatic){c.fillStyle=g.id==='water'?'#80cbea':g.id==='ball'?'#f0c48e':'#c8a3da';c.beginPath();c.arc(p.x,p.y,g.body.circleRadius||20,0,TAU);c.fill();ring(c,p.x-5,p.y-5,4,'#fff1b8',3);}else if(!g.body){drawTool(c,g.id,p.x,p.y,.8,{time:m.clock,active:true});}}articulated(c,m.doll,'buddy',{color:m.costume==='mint'?'#84cdb9':m.costume==='sunset'?'#e9b486':undefined,time:m.clock,expression:m.expression==='surprised'?'surprise':m.expression==='dizzy'?'sleep':'happy'});for(const g of m.doll.grabs.values()){ring(c,g.at.x,g.at.y,20,'#ffe3aa',2);}for(const p of m.particles){c.globalAlpha=p.life/1800;rect(c,p.x,p.y,6,10,['#eac6a6','#aca1dc','#8fd9c5'][Math.abs(Math.round(p.vx))%3],null,1);}c.globalAlpha=1;label(c,'POGO • THE SOFT-SUIT SPACE PILOT',300,55,17,'#d7c7eb');}
function doodle(c,m){drawNotebook(c);rect(c,900,200,75,250,'#d1d0d5','#77718d',7);label(c,'HOME',937,325,18,'#4d526d');bar(c,900,190,75,m.baseHP/250,'#60ab97');for(const y of m.level.paths){label(c,'→',35,y,40,'#937fa4');}for(const b of m.items){const color=b.owner?'#bc7188':'#577f9e';c.strokeStyle=color;c.lineWidth=b.shape==='wall'?9:3;c.lineCap='round';if(b.handDrawn){c.beginPath();b.points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke();if(b.points.length<3){c.beginPath();c.arc(b.x,b.y,5,0,TAU);c.fillStyle=color;c.fill();}label(c,{wall:'WALL',shield:'SHIELD',turret:'TURRET',shock:'ZAP',slow:'SLOW',star:'POWER',mine:'MINE',healer:'HEAL'}[b.shape],b.x,b.y-b.r-12,10,color);}else if(b.shape==='wall'){c.beginPath();b.points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke();}else if(b.shape==='shield'){ring(c,b.x,b.y,b.r,color,5);ring(c,b.x+3,b.y-2,b.r-7,color+'77',1);label(c,'✦',b.x,b.y,24,color);}else if(b.shape==='turret'){c.beginPath();c.moveTo(b.x,b.y-b.r);c.lineTo(b.x-b.r,b.y+b.r*.65);c.lineTo(b.x+b.r,b.y+b.r*.65);c.closePath();c.fillStyle='#f3d799';c.fill();c.stroke();c.fillStyle='#697892';c.beginPath();c.arc(b.x,b.y,9,0,TAU);c.fill();}else{ring(c,b.x,b.y,b.r+12,color+'55',2);label(c,{shock:'ϟ',slow:'◎',star:'★',mine:'✹',healer:'+'}[b.shape],b.x,b.y,b.r*1.6,color);}bar(c,b.x-20,b.y+b.r+8,40,b.hp/b.maxHP,color);if(b.level>1)label(c,'+'.repeat(b.level-1),b.x,b.y-b.r-12,17,color);}for(const e of m.enemies){drawCharacter(c,'doodle',e.x,e.y,e.kind==='boss'?1:.48,{variant:['walker','runner','flyer','armor','breaker','shielded','splitter','boss'].indexOf(e.kind),time:m.clock,color:'#746488'});bar(c,e.x-15,e.y-35,30,e.hp/e.maxHP,'#b78491');if(e.shield>0)ring(c,e.x,e.y,23,'#7a99c099',2);}for(const p of m.projectiles){c.fillStyle='#526f9b';c.beginPath();c.arc(p.x,p.y,5,0,TAU);c.fill();}for(const p of m.healing||[])label(c,'+',p.x,p.y,24,'#23805b');for(const e of m.effects||[]){if(e.kind==='heal')label(c,'+',e.x,e.y,28,'#23805b');else ring(c,e.x,e.y,140*(1-e.life/450),'#b97039',4);}for(const p of m.pointers.values()){c.strokeStyle=p.owner?'#bd7087':'#587b9e';c.lineWidth=4;c.beginPath();p.points.forEach((n,i)=>i?c.lineTo(n.x,n.y):c.moveTo(n.x,n.y));c.stroke();}}
function robot(c,m){drawWorkshopBackdrop(c);drawCharacter(c,'robot',540,240,2.8,{variant:(m.levelId-1)%9,time:m.clock,color:m.robot.color,expression:m.complete?'happy':m.testing?'surprise':'happy'});label(c,m.robot.name.toUpperCase(),535,55,23,'#f1dbaa');rect(c,275,182,510,343,'#294557','#9cb7c0',26);if(m.panelOpen){rect(c,307,224,445,264,'#142c3b','#7498a3',16);c.strokeStyle='#7c9ca14a';c.lineWidth=3;for(let y=250;y<480;y+=40){c.beginPath();c.moveTo(315,y);c.lineTo(740,y);c.stroke();}}else{for(let y=230;y<480;y+=25)rect(c,325,y,90,5,'#7399a455',null,2);label(c,m.parts.every(p=>p.fixed)?'PANEL READY':'SCAN THE FLASHING PARTS',535,450,14,'#c7d4d7');}
 for(const p of m.parts){if(!p.scanned){ring(c,p.x,p.y,28+Math.sin(m.clock/200)*3,'#f6d692',2);label(c,'?',p.x,p.y,20,'#eac992');continue;}if(!m.panelOpen&&p.fixed)continue;rect(c,p.x-57,p.y-35,114,70,p.fixed?'#3d7168':'#506c78',p.scanned?'#d7c7a1':'#7da9ba',9);if(p.scanned){if(p.removed&&!p.placed){ring(c,p.x,p.y,21,'#9ab4bf77',2);label(c,'EMPTY SOCKET',p.x,p.y,10,'#c7d4d4');}else if(p.type==='gear'){c.save();c.translate(p.x,p.y);c.rotate(p.angle);for(let i=0;i<8;i++){c.rotate(Math.PI/4);rect(c,-5,-25,10,16,'#d4c39a',null,2);}ring(c,0,0,17,'#d9caa5',8);c.restore();label(c,'▲',p.x,p.y-32,13,'#f3c984');}else if(p.type==='circuit'){const path=m.circuitPath(p);c.lineWidth=4;c.beginPath();path.forEach((n,i)=>i?c.lineTo(n.x,n.y):c.moveTo(n.x,n.y));c.strokeStyle='#829a77';c.stroke();for(let i=0;i<path.length;i++)ring(c,path[i].x,path[i].y,4,i<p.path?'#9df4cb':'#ffde99',3);}else if(p.type==='wire'||p.type==='motor'){rect(c,p.x-15,p.y-12,30,26,'#9daec0','#273c51',5);ring(c,p.x-28,p.y+15,6,'#86e2ef',4);ring(c,p.x+28,p.y+15,6,'#f0d28b',4);if(p.fixed){c.strokeStyle='#88f0c3';c.lineWidth=4;c.beginPath();c.moveTo(p.x-28,p.y+15);c.lineTo(p.x+28,p.y+15);c.stroke();}}else if(p.type==='battery'){rect(c,p.x-24,p.y-14,48,28,'#88bba2','#d0dbc1',5);label(c,['6V','12V','24V'][m.correctBattery],p.x,p.y,14,'#193e41');}else{drawTool(c,p.type==='dirty'?'brush':p.type==='wheel'?'wrench':p.type==='screw'?'screw':'assembly',p.x,p.y,.6,{time:m.clock});}label(c,p.fixed?'✓ '+p.type:p.type.toUpperCase(),p.x,p.y+27,10,p.fixed?'#b6f3d3':'#f8e2b4');if(p.progress)bar(c,p.x-35,p.y-30,70,p.progress);}}
 for(const s of m.screws){ring(c,s.x,s.y,14,s.turn>.98?'#a5e1d0':s.turn<.02?'#748492':'#eac98f',7);c.save();c.translate(s.x,s.y);c.rotate(s.turn*TAU);c.strokeStyle='#223949';c.lineWidth=3;c.beginPath();c.moveTo(-8,0);c.lineTo(8,0);c.stroke();c.restore();}rect(c,24,530,240,73,'#4c6178','#b5c5c6',14);drawTool(c,m.tool,95,562,.85);label(c,m.tool==='battery'?['A · 6V','B · 12V','C · 24V'][m.batteryType]:'NEW PARTS TRAY',174,565,13,'#eee6cf');if(m.testing){for(const [i,p]of m.testingPoints.entries()){ring(c,p.x,p.y,32,i===m.testStage?'#f8dfa5':'#709ba4',5);label(c,String(i+1),p.x,p.y,24,i<m.testStage?'#b9f5d2':'#f5e8c3');}}for(const p of m.pointers.values()){drawTool(c,p.tool,p.x,p.y,.7,{time:m.clock});}}
function wars(c,m){drawBackdrop(c,['kingdom','desert','snowy valley','castle','pirate island','forest','volcanic','future city','floating islands','training grounds'][m.field],m.clock);const ground=['#8eaa7b','#d4b68d','#d6e1da','#afb4a0','#b9bd8c','#739574','#82766a','#839ba0','#a1b2a2','#bca989'][m.field];const floor=c.createLinearGradient(0,80,0,640);floor.addColorStop(0,ground);floor.addColorStop(1,m.field===6?'#6e5f58':ground);rect(c,35,78,930,550,floor,'#dbe4c355',12);c.fillStyle='#f6e6b31a';c.beginPath();c.moveTo(35,275);c.bezierCurveTo(300,355,700,245,965,300);c.lineTo(965,365);c.bezierCurveTo(700,310,300,420,35,340);c.closePath();c.fill();for(let i=0;i<100;i++){const x=55+(i*137)%890,y=100+(i*83)%500;c.strokeStyle=i%3?'#263d3520':'#fff3ca40';c.lineWidth=1;c.beginPath();if(m.field===3||m.field===7){c.moveTo(x-6,y);c.lineTo(x+10,y);c.lineTo(x+10,y+7);}else{c.moveTo(x-3,y);c.lineTo(x,y-4);c.lineTo(x+2,y);}c.stroke();}for(const r of m.terrain())drawMaterial(c,m.field===2?'ice':'stone',r.x-r.w/2,r.y-r.h/2,r.w,r.h,{time:m.clock});if(m.phase==='build'){rect(c,45,85,415,490,'#77c9bc0d','#80c3c555',16);rect(c,540,85,415,490,'#dc9db30d','#d4a3ba55',16);label(c,'YOUR DEPLOYMENT',250,62,17,'#9ce2d1');label(c,m.mode==='clash'?'OTHER PLAYER':'OPPOSING ARMY',750,62,17,'#e6b7c6');for(const b of [...m.items,...(!['sandbox','clash'].includes(m.mode)?m.enemy.map(b=>({...b,side:1})):[])]){const p=m.unitArt(b);drawWarUnit(c,p,m.clock);if(m.selected===b)ring(c,b.x,b.y,36,'#ffe6ac',3);}}else{for(const u of [...m.units].sort((a,b)=>a.y-b.y)){if(u.removed)continue;if(!u.alive||m.clock<(u.downUntil||0)){c.globalAlpha=u.alive?1:Math.max(.2,1-(m.clock-u.deadAt)/7000);articulated(c,u.doll,'soldier',{unit:u.id,color:u.side?'#ce8fa7':'#86bdd1',time:m.clock,expression:u.alive?'surprise':'sleep'});c.globalAlpha=1;}else drawWarUnit(c,u,m.clock);if(u.alive)bar(c,u.x-17,u.y-96*u.scale,34,u.hp/u.maxHP,u.side?'#e4acbb':'#98dfd0');}for(const p of m.projectiles)drawWarProjectile(c,p,m.clock);for(const e of m.effects){c.save();c.globalAlpha=Math.min(1,e.life/(e.maxLife||500));const color=e.kind==='heal'?'#a1e8b8':e.kind==='ice'?'#a0e9fa':e.kind==='block'?'#b9dae0':e.kind==='magic'?'#c99cfc':'#e9ca99';if(e.kind==='swing'){c.strokeStyle=color;c.lineWidth=4;c.beginPath();c.moveTo(e.from.x,e.from.y);c.lineTo(e.to.x,e.to.y);c.stroke();}else{const age=1-e.life/(e.maxLife||500);c.strokeStyle=color;c.fillStyle=color;c.lineWidth=e.kind==='heavy'?4:2;c.beginPath();c.ellipse(e.from.x,e.from.y,5+age*(e.kind==='heavy'?38:14),3+age*8,0,0,TAU);if(['dust','smoke'].includes(e.kind))c.fill();else c.stroke();}c.restore();}}}
